    @staticmethod
    def create_qsl_source_xyz(datasource: dict) -&gt; XYZSource:
        return XYZSource.from_qgis_decoded_uri(datasource)

    @staticmethod
    def create_qsl_source_wmts(datasource: dict) -&gt; WmtsSource:
